entries[19326] = { ["name"] = "Muster: Macht der Holzschlundfeste", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (290)\nBenötigt Holzschlundfeste\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung der Macht der Holzschlundfeste.\nMacht der Holzschlundfeste\nWird beim Anlegen gebunden\nTaille Leder\n93 Rüstung\n+9 Ausdauer\nHaltbarkeit 35 / 35\nBenötigt Stufe 53\nAnlegen: Erhöht die Angriffskraft um 42.\nBenötigt Unverwüstliches Leder (30), Essenz des Lebens (4), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)" }
